CREATE TABLE IF NOT EXISTS users (id SERIAL PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(255) UNIQUE NOT NULL, password_hash TEXT NOT NULL, role VARCHAR(20) NOT NULL CHECK (role IN ('Admin','Sales','Warehouse','Accounts')), created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS customers (id SERIAL PRIMARY KEY, name VARCHAR(150) NOT NULL, mobile VARCHAR(20) NOT NULL, email VARCHAR(255), business_name VARCHAR(150), gst_number VARCHAR(30), customer_type VARCHAR(20) NOT NULL CHECK (customer_type IN ('Retail','Wholesale','Distributor')), address TEXT, status VARCHAR(20) NOT NULL DEFAULT 'Lead' CHECK (status IN ('Lead','Active','Inactive')), follow_up_date DATE, notes TEXT, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS customer_followups (id SERIAL PRIMARY KEY, customer_id INT NOT NULL REFERENCES customers(id) ON DELETE CASCADE, note TEXT NOT NULL, follow_up_date DATE, created_by INT REFERENCES users(id), created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS products (id SERIAL PRIMARY KEY, name VARCHAR(150) NOT NULL, sku VARCHAR(80) UNIQUE NOT NULL, category VARCHAR(100) NOT NULL, unit_price NUMERIC(12,2) NOT NULL CHECK(unit_price >= 0), current_stock INT NOT NULL DEFAULT 0 CHECK(current_stock >= 0), min_stock_alert INT NOT NULL DEFAULT 0 CHECK(min_stock_alert >= 0), warehouse_location VARCHAR(100), created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS stock_movements (id SERIAL PRIMARY KEY, product_id INT NOT NULL REFERENCES products(id), quantity_changed INT NOT NULL CHECK(quantity_changed > 0), movement_type VARCHAR(3) NOT NULL CHECK(movement_type IN ('IN','OUT')), reason TEXT NOT NULL, created_by INT REFERENCES users(id), created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS challans (id SERIAL PRIMARY KEY, challan_number VARCHAR(40) UNIQUE NOT NULL, customer_id INT NOT NULL REFERENCES customers(id), total_quantity INT NOT NULL DEFAULT 0, status VARCHAR(20) NOT NULL DEFAULT 'Draft' CHECK(status IN ('Draft','Confirmed','Cancelled')), created_by INT REFERENCES users(id), created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS challan_items (id SERIAL PRIMARY KEY, challan_id INT NOT NULL REFERENCES challans(id) ON DELETE CASCADE, product_id INT REFERENCES products(id), product_name VARCHAR(150) NOT NULL, sku VARCHAR(80) NOT NULL, unit_price NUMERIC(12,2) NOT NULL, quantity INT NOT NULL CHECK(quantity > 0));
